"use client";

// beacon-404 · 404lab
// Requires ./chrome.tsx and the 404lab tokens.

import { motion, useReducedMotion } from "motion/react";
import { Caption, Foot, Plate, Screen } from "./chrome";

/* ---------------------------------- beacon --------------------------------- */

export function BeaconDemo() {
  const reduce = useReducedMotion();

  return (
    <Screen className="bg-[#060708]">
      <Plate src="/worlds/w-star-trails.webp" className="brightness-[0.52]" />
      <div className="absolute inset-0 bg-[linear-gradient(180deg,rgba(8,9,10,0.3)_0%,rgba(8,9,10,0.08)_50%,rgba(8,9,10,0.86)_100%)]" />
      <div className="absolute inset-x-0 bottom-0 h-[34%] bg-[linear-gradient(180deg,transparent,rgba(8,9,10,0.95))]" />

      <div className="absolute bottom-[18%] left-[70%] z-10 h-[74px] w-[22px] -translate-x-1/2">
        <div className="absolute bottom-0 left-1/2 h-full w-[3px] -translate-x-1/2 bg-[linear-gradient(180deg,rgba(242,237,227,0.38),rgba(242,237,227,0.08))]" />
        <div className="absolute bottom-0 left-1/2 h-2 w-7 -translate-x-1/2 rounded-t-[1px] bg-[#0c0e10]" />
        <span className="absolute left-1/2 top-0 size-1.5 -translate-x-1/2 -translate-y-1/2 rounded-full bg-amber shadow-[0_0_14px_3px_rgba(233,184,113,0.35)]" />
        <motion.div
          aria-hidden
          className="absolute bottom-0 left-1/2 h-[240px] w-[240px] -translate-x-1/2 origin-bottom"
          animate={reduce ? undefined : { rotate: 360 }}
          transition={{ duration: 12, ease: "linear", repeat: Infinity }}
        >
          {[0, 180].map((turn) => (
            <div
              key={turn}
              className="absolute inset-0 opacity-80 mix-blend-screen"
              style={{
                transform: `rotate(${turn}deg)`,
                clipPath: "polygon(50% 100%, 0 0, 24% 0)",
                background:
                  "linear-gradient(180deg,rgba(255,225,177,0.5),rgba(233,184,113,0.06) 78%)",
                filter: "blur(1.5px)",
                transformOrigin: "bottom center",
              }}
            />
          ))}
        </motion.div>
        <span
          aria-hidden
          className="absolute left-1/2 top-0 size-7 -translate-x-1/2 -translate-y-1/2 rounded-full bg-amber/20 blur-md"
        />
      </div>

      <div className="absolute inset-0 z-10 flex flex-col items-center justify-center gap-2.5">
        <span className="display text-[72px] leading-none text-fg drop-shadow-[0_2px_16px_rgba(8,9,10,0.8)]">
          404
        </span>
        <span className="lab-mono text-[10px] text-white/65">
          a signal with no receiver
        </span>
      </div>

      <div className="pointer-events-none absolute left-4 top-9 z-20 lab-mono text-[9px] leading-relaxed text-white/45">
        <p>51°30′N</p>
        <p>0°07′W</p>
      </div>
      <div className="pointer-events-none absolute right-4 top-9 z-20 text-right lab-mono text-[9px] leading-relaxed text-white/45">
        <p>BEAM 04</p>
        <p className="text-amber/70">NO ANSWER</p>
      </div>

      <Caption label="404 / beacon" />
      <Foot method="beam · 12s sweep" />
    </Screen>
  );
}

"use client";

import Image from "next/image";
import { motion, useReducedMotion } from "motion/react";
import { useEffect, useRef, useState } from "react";
import { ArrowUpRight, Check, Copy } from "lucide-react";

export const EASE = [0.22, 1, 0.36, 1] as const;

/* Every card shares the same framing so the grid reads as one set. */

export function Caption({
  label,
  className = "",
}: {
  label: string;
  className?: string;
}) {
  return (
    <span
      className={`pointer-events-none absolute left-4 top-3 z-20 lab-mono text-[10px] tracking-[0.02em] text-white/75 [text-shadow:0_1px_3px_rgba(8,9,10,0.6)] ${className}`}
    >
      {label}
    </span>
  );
}

export function HomeLink({ label = "back home" }: { label?: string }) {
  return (
    <span className="pointer-events-none inline-flex items-center gap-1 lab-mono text-[10px] text-white/70">
      {label}
      <ArrowUpRight className="size-3" strokeWidth={1.5} />
    </span>
  );
}

export function Foot({
  method,
  label,
}: {
  method: string;
  label?: string;
}) {
  return (
    <div className="pointer-events-none absolute inset-x-0 bottom-0 z-20 flex items-center justify-between px-4 pb-3">
      <HomeLink label={label} />
      <span className="lab-mono text-[10px] text-white/50">{method}</span>
    </div>
  );
}

const SCREEN =
  "group @container relative h-full w-full overflow-hidden bg-ink-900";

export function Screen({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"div">) {
  return (
    <div {...rest} className={`${SCREEN} ${className}`}>
      {children}
    </div>
  );
}

export function ScreenButton({
  className = "",
  children,
  ...rest
}: React.ComponentProps<"button">) {
  return (
    <button
      type="button"
      {...rest}
      className={`${SCREEN} cursor-default text-left ${className}`}
    >
      {children}
    </button>
  );
}

export function Plate({
  src,
  className = "",
  sizes = "(max-width: 768px) 100vw, 33vw",
  opacity,
  position = "center",
}: {
  src: string;
  className?: string;
  sizes?: string;
  opacity?: number;
  position?: string;
}) {
  return (
    <Image
      src={src}
      alt=""
      fill
      sizes={sizes}
      className={`object-cover ${className}`}
      style={{ opacity, objectPosition: position }}
    />
  );
}

/* --------------------------------- helpers -------------------------------- */

export function useReplay() {
  const [run, setRun] = useState(0);
  return { run, replay: () => setRun((n) => n + 1) };
}

export function useStill() {
  return useReducedMotion() ?? false;
}

export const clamp = (v: number, min: number, max: number) =>
  Math.max(min, Math.min(max, v));

/* ------------------------------- install bits ------------------------------ */

export function CopyCommand({
  command,
  className = "",
}: {
  command: string;
  className?: string;
}) {
  const [done, setDone] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );

  async function copy() {
    try {
      await navigator.clipboard.writeText(command);
      setDone(true);
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => setDone(false), 1600);
    } catch {
      setDone(false);
    }
  }

  return (
    <button
      type="button"
      onClick={copy}
      aria-label={`Copy ${command}`}
      className={`group/copy flex w-full items-center justify-between gap-4 rounded-control border border-line bg-ink-900 px-3 py-2.5 text-left transition-colors duration-200 hover:border-line-2 active:translate-y-px ${className}`}
    >
      <code className="min-w-0 break-all lab-mono text-[10px] text-fg-2 sm:truncate lg:text-[12px]">
        <span className="mr-1.5 text-amber/80">$</span>
        {command}
      </code>
      <span
        aria-live="polite"
        className="shrink-0 text-fg-3 transition-colors duration-200 group-hover/copy:text-fg"
      >
        {done ? (
          <Check className="size-4 text-amber" strokeWidth={1.5} />
        ) : (
          <Copy className="size-4" strokeWidth={1.5} />
        )}
      </span>
    </button>
  );
}

export function Reveal({
  children,
  delay = 0,
  className = "",
}: {
  children: React.ReactNode;
  delay?: number;
  className?: string;
}) {
  const reduce = useReducedMotion();
  return (
    <motion.div
      className={className}
      initial={reduce ? false : { opacity: 0, y: 10 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-60px" }}
      transition={{ duration: 0.55, ease: EASE, delay }}
    >
      {children}
    </motion.div>
  );
}
